arguments.command:
curl -s -X POST https://slack.com/api/users.list -H 'Authorization: Bearer <TOKEN>' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit()
for u in d['members']:
    name=(u.get('profile',{}).get('real_name') or u.get('name','') or '').lower()
    if 'priya' in name or (u.get('profile',{}).get('display_name','') or '').lower().find('priya')>=0:
        print(u['id'], u.get('profile',{}).get('real_name'), u.get('profile',{}).get('display_name'))
"

